// TypeScript emitter: model -> { types, client } source strings. Pure.

import { refKey, oneLine } from "./model.mjs";
import { isPlainIdent } from "./names.mjs";

export const TS_BANNER =
  "// DO NOT EDIT. Generated by sdk/generate.mjs from docs/api/openapi.json.\n" +
  "// Regenerate with: node sdk/generate.mjs\n";

function refName(ref, ctx) {
  const key = refKey(ref);
  const name = ctx.typeNames.get(key);
  if (!name) throw new Error(`$ref to unknown schema: ${ref}`);
  return ctx.prefix + name;
}

function paren(t) {
  return /[|&]/.test(t) ? `(${t})` : t;
}

function propKey(name) {
  return isPlainIdent(name) ? name : JSON.stringify(name);
}

function isEmptySchema(s) {
  return s == null || s === true || (typeof s === "object" && Object.keys(s).length === 0);
}

/** TypeScript type expression for a JSON Schema. `ctx = { typeNames: Map, prefix: "" | "T." }`. */
export function tsType(s, ctx, depth = 0) {
  if (s === false) return "never";
  if (isEmptySchema(s)) return "unknown";
  if (s.$ref) return refName(s.$ref, ctx);
  if (Array.isArray(s.enum)) {
    return s.enum.length ? s.enum.map((v) => JSON.stringify(v)).join(" | ") : "never";
  }
  const alt = s.oneOf ?? s.anyOf;
  if (Array.isArray(alt) && alt.length) {
    return alt.map((x) => paren(tsType(x, ctx, depth))).join(" | ");
  }
  if (Array.isArray(s.allOf) && s.allOf.length) {
    return s.allOf.map((x) => paren(tsType(x, ctx, depth))).join(" & ");
  }
  const type = Array.isArray(s.type) ? s.type.find((t) => t !== "null") : s.type;
  switch (type) {
    case "string":
      return s.format === "binary" ? "Blob" : "string";
    case "integer":
    case "number":
      return "number";
    case "boolean":
      return "boolean";
    case "null":
      return "null";
    case "array":
      return `${paren(tsType(s.items ?? {}, ctx, depth))}[]`;
    case "object":
      return objectType(s, ctx, depth);
    default:
      return s.properties ? objectType(s, ctx, depth) : "unknown";
  }
}

function isOptional(schema, key) {
  const required = Array.isArray(schema.required) && schema.required.includes(key);
  const prop = schema.properties[key];
  // A required primitive carries its Java default: the server fills it in when absent, so it is optional on input.
  const hasDefault = prop && typeof prop === "object" && "default" in prop;
  return !required || hasDefault;
}

function objectType(s, ctx, depth) {
  const props = s.properties;
  if (props && Object.keys(props).length > 0) {
    const pad = "  ".repeat(depth + 1);
    let out = "{\n";
    if (s.additionalProperties === true) out += `${pad}[key: string]: unknown;\n`;
    for (const key of Object.keys(props)) {
      const prop = props[key];
      if (prop && typeof prop === "object" && prop.description) {
        out += `${pad}/** ${oneLine(prop.description)} */\n`;
      }
      out += `${pad}${propKey(key)}${isOptional(s, key) ? "?" : ""}: ${tsType(prop, ctx, depth + 1)};\n`;
    }
    return `${out}${"  ".repeat(depth)}}`;
  }
  if (s.additionalProperties && s.additionalProperties !== true) {
    return `Record<string, ${tsType(s.additionalProperties, ctx, depth)}>`;
  }
  return "Record<string, unknown>";
}

/** types.ts: one exported declaration per component schema. */
export function emitTypes(model) {
  const ctx = { typeNames: model.typeNames, prefix: "" };
  let out = `${TS_BANNER}\n`;
  for (const { name, schema } of model.schemas) {
    if (schema && schema.description) out += `/** ${oneLine(schema.description)} */\n`;
    const isObject =
      schema && (schema.type === "object" || schema.properties) && schema.properties && Object.keys(schema.properties).length > 0;
    if (isObject) {
      out += `export interface ${name} ${objectType(schema, ctx, 0)}\n\n`;
    } else {
      out += `export type ${name} = ${tsType(schema, ctx, 0)};\n\n`;
    }
  }
  out += "export {};\n";
  return out;
}

function paramsObject(params, ctx) {
  const fields = params.map(
    (p) => `${propKey(p.name)}${p.required ? "" : "?"}: ${tsType(p.schema, ctx)}`,
  );
  return `{ ${fields.join("; ")} }`;
}

function templatePath(op) {
  if (op.pathParams.length === 0) return JSON.stringify(op.path);
  let out = op.path.replace(/\\/g, "\\\\").replace(/`/g, "\\`").replace(/\$\{/g, "\\${");
  for (const p of op.pathParams) {
    out = out.split(`{${p.name}}`).join(`\${encodeURIComponent(String(${p.ts}))}`);
  }
  return `\`${out}\``;
}

function bodyType(body, ctx) {
  if (body.kind === "json") return tsType(body.schema, ctx);
  if (body.kind === "multipart") return "FormData";
  if (body.kind === "text") return "string";
  return "BodyInit";
}

function returnType(op, ctx) {
  switch (op.response.kind) {
    case "sse":
      return "AsyncGenerator<string, void, undefined>";
    case "void":
      return "Promise<void>";
    case "text":
      return "Promise<string>";
    case "blob":
      return "Promise<Blob>";
    default:
      return `Promise<${tsType(op.response.schema, ctx)}>`;
  }
}

function emitOperation(op, ctx) {
  const q = op.queryParams;
  const h = op.headerParams;
  const reqQuery = q.some((p) => p.required);
  const reqHeaders = h.some((p) => p.required);
  const optionsRequired = reqQuery || reqHeaders;

  let optionsType = "CallOptions";
  if (q.length || h.length) {
    const Q = q.length ? paramsObject(q, ctx) : "QueryParams";
    const H = h.length ? paramsObject(h, ctx) : "HeaderParams";
    optionsType = `CallOptions<${Q}, ${H}>`;
    if (reqQuery) optionsType += ` & { query: ${Q} }`;
    if (reqHeaders) optionsType += ` & { headers: ${H} }`;
  }

  const args = op.pathParams.map((p) => `${p.ts}: ${tsType(p.schema, ctx)}`);
  if (op.body) {
    // A required parameter may not follow an optional one, so spell the optional body out when options are required.
    const t = bodyType(op.body, ctx);
    args.push(
      op.body.required ? `body: ${t}` : optionsRequired ? `body: ${paren(t)} | undefined` : `body?: ${t}`,
    );
  }
  args.push(`options${optionsRequired ? "" : "?"}: ${optionsType}`);

  const fields = ["...options", `method: ${JSON.stringify(op.verb.toUpperCase())}`, `path: ${templatePath(op)}`];
  if (op.body) {
    fields.push("body");
    if (op.body.kind !== "json") fields.push(`bodyType: ${JSON.stringify(op.body.kind)}`);
    if (op.body.kind === "text" || op.body.kind === "raw") fields.push(`contentType: ${JSON.stringify(op.body.mediaType)}`);
  }
  const kind = op.response.kind;
  if (kind === "void" || kind === "text" || kind === "blob") fields.push(`response: ${JSON.stringify(kind)}`);

  const ret = returnType(op, ctx);
  const call =
    kind === "sse"
      ? `this.http.stream({ ${fields.join(", ")} })`
      : `this.http.request<${ret.replace(/^Promise<(.*)>$/s, "$1")}>({ ${fields.join(", ")} })`;

  const title = oneLine(op.summary) || op.id;
  let doc = `  /**\n   * ${title}.\n   * \`${op.verb.toUpperCase()} ${op.path}\`\n`;
  if (op.description) doc += `   *\n   * ${oneLine(op.description)}\n`;
  if (op.deprecated) doc += "   * @deprecated\n";
  doc += "   */\n";

  return `${doc}  ${op.tsName}(${args.join(", ")}): ${ret} {\n    return ${call};\n  }\n`;
}

/** client.ts: one API class per tag plus the VegadutaClient facade. */
export function emitClient(model) {
  const ctx = { typeNames: model.typeNames, prefix: "T." };
  let out = `${TS_BANNER}\n`;
  out += 'import { HttpClient } from "../runtime";\n';
  out += 'import type { CallOptions, ClientOptions, HeaderParams, QueryParams } from "../runtime";\n';
  out += 'import type * as T from "./types";\n\n';
  for (const g of model.groups) {
    out += `export class ${g.className} {\n  private readonly http: HttpClient;\n\n  constructor(http: HttpClient) {\n    this.http = http;\n  }\n`;
    for (const op of g.operations) out += `\n${emitOperation(op, ctx)}`;
    out += "}\n\n";
  }
  out += "/** Entry point: one property per API group (controller). */\nexport class VegadutaClient {\n  readonly http: HttpClient;\n";
  for (const g of model.groups) out += `  readonly ${g.tsProp}: ${g.className};\n`;
  out += "\n  constructor(options: ClientOptions = {}) {\n    this.http = new HttpClient(options);\n";
  for (const g of model.groups) out += `    this.${g.tsProp} = new ${g.className}(this.http);\n`;
  out += "  }\n}\n";
  return out;
}
